"""MG163 audited report, compact decisions and verified local raw manifest."""
import time,hashlib,shutil,gzip,json,traceback
import numpy as np
from run_mg163_long import PUBLIC as BASE,BASE as RAW,ROOT,read,atomic_json
from mg161_local_shape import LocalShape

def report():
    start=time.perf_counter();attempt=BASE/'report_attempt_v2.json';assert not attempt.exists();atomic_json(attempt,dict(status='RUNNING'))
    try:
        s=read(BASE/'fresh_candidate_scores.json');a=read(RAW/'P1_analysis_results.json');r=read(BASE/'fresh_separate_recomputation.json');run=read(BASE/'attempt.json');plan=read(BASE/'plan.json');ledger=read(RAW/'production/ledger.json')
        assert a['passed'] and r['passed'] and s['pilot_separation_supported']==r['pilot_separation_supported']
        with np.load(RAW/'prepared_inputs.npz') as z:model=LocalShape(z['reference'][1],z['initial'][1],float(z['omega']))
        manifest={p.relative_to(RAW).as_posix():dict(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in RAW.rglob('*') if p.is_file()}
        atomic_json(BASE/'local_raw_manifest.json',dict(directory=str(RAW),full_raw_published=False,files=manifest,total_bytes=sum(v['bytes'] for v in manifest.values()),retention='Complete physical raw files verified locally by this report; no immutable Git commit claimed. Full causal recomputation requires local files.'))
        for old,new in [('P1_analysis_results.json','causal_audit.json'),('P1_analysis_attempt.json','causal_audit_attempt.json')]:shutil.copy2(RAW/old,BASE/new)
        shutil.copy2(RAW/'production/ledger.json',BASE/'compute_ledger.json')
        # Compact lossless export of all decision fits/labels, not raw count or event fields.
        (BASE/'candidate_scores.json.gz').write_bytes(gzip.compress((BASE/'fresh_candidate_scores.json').read_bytes(),mtime=0))
        rows=[];stocks=[]
        for j in s['jobs']:
            with np.load(RAW/'production'/j['id']/'observations.npz') as z:times=z['times'];counts=z['counts']
            for v in j['outcomes']:
                side=v['side'];fits=v['fits'];rel=[f['amplitude']/model.initial_amplitude for f in fits];edge=v['boundary_advisory_frames'];first=next((i for i,l in enumerate(v['labels']) if l!='core_compatible'),None)
                rows.append(dict(id=j['id'],condition=j['condition'],side=side,compatible_frames=v['compatible_frames'],all_compatible=v['all_compatible'],any_compatible=v['any_compatible'],boundary_frames=len(edge),first_boundary_time=float(times[edge[0]]) if edge else None,first_compatible_time=next((float(times[i]) for i,l in enumerate(v['labels']) if l=='core_compatible'),None),initial_compatible=v['labels'][0]=='core_compatible',first_noncompatible_bracket=v['first_noncompatible_bracket'] if first not in (None,0) else None,initially_noncompatible=first==0,first_noncompatible_label=v['labels'][first] if first is not None else None,relative_amplitude_range=[min(rel),max(rel)],scale_range=[min(f['scale'] for f in fits),max(f['scale'] for f in fits)],label_counts={l:v['labels'].count(l) for l in sorted(set(v['labels']))}))
                total=counts[:,side].sum(axis=2);stocks.append(dict(id=j['id'],side=side,A_initial=int(total[0,3]),A_final=int(total[-1,3]),B_initial=int(total[0,4]),B_final=int(total[-1,4]),Z_added=int(total[-1,5]-total[0,5]),W_added=int(total[-1,6]-total[0,6])))
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt
        fig,axes=plt.subplots(3,1,figsize=(9,8),sharex=True,layout='constrained')
        for j in s['jobs']:
            for v in j['outcomes']:
                t=np.arange(1001)*.001;fits=v['fits'];prepared=j['condition']=='prepared';color='tab:blue' if prepared else 'tab:orange';style='-' if v['side']==0 else '--'
                axes[0].plot(t,[f['amplitude']/model.initial_amplitude for f in fits],color=color,ls=style,alpha=.6,lw=.9)
                if prepared:
                    axes[1].plot(t,[f['scale'] for f in fits],color=color,ls=style,alpha=.6,lw=.9)
                    threshold=read(ROOT/'results/MG12H3/noise_aware_shape/calibration.json')['residual_threshold']
                    axes[2].plot(t,[f['residual']/threshold for f in fits],color=color,ls=style,alpha=.6,lw=.9)
        axes[0].axhline(.5,color='black',ls=':',label='Compatibility amplitude threshold');axes[0].axhline(.6,color='gray',ls=':',label='Boundary advisory amplitude')
        axes[0].set_ylabel('Fitted relative amplitude');axes[0].set_title('MG163: blue prepared cores; orange homogeneous controls')
        axes[0].legend(fontsize=8);axes[1].set_ylabel('Prepared fitted scale');axes[2].set_ylabel('Prepared residual / threshold');axes[2].axhline(1,color='black',ls=':');axes[2].set_xlabel('Post-preparation model time (no seconds conversion)')
        for ax in axes:ax.grid(alpha=.2)
        fig.savefig(BASE/'MG163_core_histories.png',dpi=160);plt.close(fig)
        atomic_json(BASE/'decision_summary.json',dict(supported=s['pilot_separation_supported'],rows=rows,stocks=stocks,limitations='Finite sampled cohort; no population lifetime, between-frame persistence, continuum or physical-particle claim.'))
        prep=[x for x in rows if x['condition']=='prepared'];control=[x for x in rows if x['condition']=='homogeneous'];supported=s['pilot_separation_supported'];nret=sum(x['all_compatible'] for x in prep);nedge=sum(x['boundary_frames'] for x in prep);nc=sum(x['any_compatible'] for x in control)
        if supported:
            summary='Every prepared Model G pattern retained a recognizable local core at every sampled observation through T=1, ten times the previous pilot horizon, and none of the homogeneous controls produced a compatible core. No prepared frame triggered a boundary warning. This strengthens the evidence for persistence of the simulated local pattern under the tested finite-source dynamics and two tick resolutions. It is evidence about eight prepared marginal paths from four independent pairs over a finite sampled horizon; it does not establish permanent particles, a population lifetime, quantum behavior, or physical units.'
        else:
            summary=f'The tenfold-longer test did not meet the frozen clear-case separation criterion: {nret} of eight prepared marginal paths remained core-compatible at every observation, {nedge} prepared frames carried boundary warnings, and {nc} of eight homogeneous marginal paths produced at least one compatible detection. All prepared paths first failed the shape-residual requirement between T=0.205 and 0.460, while their fitted amplitude remained above the minimum throughout. The core therefore did not simply fade away: agreement with the fixed template became inadequate under the longer evolving dynamics. This identifies a limit or complication that the short pilot could not expose. The retained labels and first-loss brackets distinguish loss of template compatibility, uncertain boundary fits and control detections; none automatically establishes physical particle death or creation. Four independent pairs per condition cannot establish a population lifetime.'
        lines=['# MG163 - longer-horizon pattern-persistence results','',summary,'','![Fitted amplitude and prepared scale histories](MG163_core_histories.png)','','## Frozen outcome','',f"**Clear-case finite-cohort separation: {'SUPPORTED' if supported else 'NOT ESTABLISHED'}.** PI closure pending. Approved registration `0000067` was published before draws. All eight registered jobs completed; no retries, replacement paths, exclusions or threshold changes.",'',
        'Four fresh prepared and four mass-matched homogeneous independent seed pairs, each at ticks 0.0001 and 0.00002, were run for post-preparation T=1 with 1001 observations at 0.001 spacing. Sites = 500, Omega=10, finite local A/B supplies and retained Z/W products remain unchanged. There is no conversion of model time or length to physical seconds or metres. Within-pair tick paths and within-path frames are correlated.','',
        '| Pair | Tick | Compatible frames | Boundary warnings | First sampled noncompatible bracket | First noncompatible label |','|---|---:|---:|---:|---|---|']
        for x in rows:
            bracket=x['first_noncompatible_bracket'];text='initially noncompatible' if x['initially_noncompatible'] else ('none through1' if bracket is None else f"({bracket[0]:.6g}, {bracket[1]:.6g}]")
            lines.append(f"| {x['id']} | {plan['deltas'][x['side']]:.6g} | {x['compatible_frames']}/1001 | {x['boundary_frames']} | {text} | {x['first_noncompatible_label'] or 'none'} |")
        lines+=['','All first prepared noncompatible labels were `shape_mismatch`, rather than weak amplitude, excessive dilation or a boundary warning. Prepared relative amplitudes stayed between 0.725182 and 1.40089, fitted scales between 0.875 and 1.125. Those ranges alone do not establish shape retention because residual and competing-core requirements also apply. The plot uses solid lines for coarse ticks and dashed lines for fine ticks; a prepared residual/threshold ratio above 1 fails the shape requirement. No threshold was changed after seeing these outcomes.','', 'A boundary warning is the frozen engineering sensitivity rule (relative amplitude <= 0.6 or fitted scale within 0.125 of 0.5 or 2), not a confidence interval or a hidden label change. First loss is bracketed between sampled observations, and loss/recovery between observations cannot be excluded. Initial absence in controls is not a post-initial loss. `decision_summary.json` preserves first advisory times, label counts and fitted ranges; `candidate_scores.json.gz` retains all fitted values, point labels and advisory frame indices losslessly.','',
        '## Checks, dynamics and inference limits','',
        f"The saved-data audit passed {a['checkpoint_chain_endpoints']} marginal checkpoint endpoints, checked exact RNG chains/count reconstruction/channel histograms and source/spec bindings, and verified source/product reaction accounts. It replayed {a['sentinel_events']:,} events in the fixed 200 sentinel segments (100 each in prepared/control replicate 0). Other segments retain checkpoint/histogram/RNG verification but not full causal event replay. This is the approved 10% sentinel coverage, not a full-history event audit.",'',
        f"Separate direct spatial weighted sums checked all {r['fields_checked']} fitted fields over the 23-scale, 500-position bank, including global maximum, secondary score, residual, classification, warnings and final verdict. Both checks passed. Shared input fields/templates/smoothing and same-author work remain dependencies; this is not external replication.",'',
        'Finite-source depletion remains part of the model, with no replenishment. Initial/final A/B stocks and Z/W increases are exported per path in `decision_summary.json`. Conservation bookkeeping is not a demonstrated mapping to physical energy or a vacuum field. Agreement in this operational criterion at two ticks is not a new quantitative tick-equivalence or continuum-convergence result. The historical whole-domain metric was audited descriptively; MG160-P1 and MG162 outcomes remain unchanged. Near-boundary instrument qualification and wider physical interpretation remain unresolved.','',
        '## Runtime and retention','',
        f"Wall time {run['wall_seconds']/3600:.6g} hours; charged worker time {run['charged_worker_seconds']:.6g} seconds ({run['charged_worker_seconds']/3600:.6g} core-hours), below 800000 seconds. Longest charged job {max(x['charged_worker_seconds'] for x in ledger['records']):.6g} seconds, below 100000. At most 8 workers, with one library thread each. No failed scientific jobs or budget stops. Causal audit {a['elapsed_seconds']:.6g} seconds; independent fit recomputation {r['elapsed_seconds']:.6g} seconds. Preparation and analysis attempt records retain active timings; waiting is excluded.",'',
        f"Verified local full raw payload at report generation: {sum(v['bytes'] for v in manifest.values())/1e9:.6g} GB, below 4 GB. Full arrays/checkpoints/sentinel event histories remain in `local_raw/MG163_long_horizon`; public package contains compact decisions, summaries, hashes, source and plots only. `local_raw_manifest.json` records every retained filename, size and SHA-256. Physical files were checked, not merely their earlier hashes; no immutable Git archive is claimed. Full causal reproduction needs the local archive.",'',
        '## Recommended next step','',
        ('After PI sign-off, prepare a controlled stress study that distinguishes continued powered persistence from dependence on finite A/B stock. First use the saved stock histories and measured costs to choose a depletion-relevant horizon or a separately specified supply intervention, with homogeneous controls. Preserve this frozen instrument and account explicitly for boundary-sensitive fits. Another tenfold extension would be expensive; establish the scientific contrast and budget before launching it.' if supported else 'Inspect the already-saved first noncompatible/advisory/control-crossing neighborhoods to distinguish template mismatch, boundary sensitivity, competing cores and depletion. Treat this as diagnostic analysis, preserving the frozen negative/incomplete separation verdict. Propose any instrument change or new dynamical intervention as a separate registered study; do not tune this test into a pass.'),
        '','No further simulations are authorized or started by this report.','']
        (BASE/'MG163_long_horizon_results.md').write_text('\n'.join(lines),encoding='utf-8')
        atomic_json(attempt,dict(status='COMPLETE',elapsed_seconds=time.perf_counter()-start))
    except BaseException:atomic_json(attempt,dict(status='FAILED',elapsed_seconds=time.perf_counter()-start,error=traceback.format_exc()));raise
if __name__=='__main__':report()
